export const normalizeTags = values => {
  // Trim, lowercase, filter empties, remove duplicates, and sort alphabetically
  const processed = values.map(v => v ? v.trim().toLowerCase() : null);
  const nonEmpty = processed.filter(v => v !== null && v.length > 0);
  const unique = [...new Set(nonEmpty)];
  return unique.sort();
};

export const tagLabel = value => normalize(value);"}

